from pathlib import Path
import subprocess, json, hashlib, zlib, base64
from PIL import Image

ROOT = Path(r'C:\Users\brand\OneDrive\Documents\dead-street')
BRANCH = 'build/arsenal-checkpoint-20260911'
DATA = json.loads(zlib.decompress(base64.b64decode('')))

def git(*args):
    return subprocess.check_output(['git', *args], cwd=ROOT, text=True).strip()

assert git('rev-parse', 'HEAD') == 'db92794c98981b4a12c45c4863c84480cfb7c1a7', 'HEAD changed'
assert git('branch', '--show-current') == BRANCH, 'Branch changed'
assert git('remote', 'get-url', 'origin') == 'https://github.com/LeadLasso-LL/DEADSTREET.git'
assert not git('diff', '--cached', '--name-only'), 'Existing staged work'
applied = json.loads((ROOT/'tools/vehicle_fleet/review_2034/applied.json').read_text())
assert applied['passed'] and applied['head_before'] == git('rev-parse', 'HEAD')
reports = {n: json.loads((ROOT/'tools/vehicle_fleet'/n).read_text()) for n in ['validation.json', 'validation_mixed.json', 'native_review/report.json']}
assert all(not r['errors'] for r in reports.values())
assert reports['validation.json']['checks'] == 3730
assert reports['validation_mixed.json']['checks'] == 43
assert reports['native_review/report.json']['scenarios'] == 6
for name, marker in [('compile_fleet','FLEET_COMPILE []'), ('validate_panel','FLEET_PANEL []'), ('native','FLEET_NATIVE_VISUAL []')]:
    assert marker in (ROOT/'tools/vehicle_fleet/review_2034'/f'{name}.log').read_text(encoding='utf-8'), name
for name, expected in DATA['reviewed_hashes'].items():
    p = ROOT/name
    if name.endswith('.png'):
        content = Image.open(p).convert('RGBA').tobytes()
    else:
        content = p.read_text(encoding='utf-8').encode() if name.endswith(('.py','.gd','.json','.md')) else p.read_bytes()
    assert hashlib.sha256(content).hexdigest() == expected, name+' differs from reviewed source/art'
for name, item in DATA['docs'].items():
    assert hashlib.sha256((ROOT/name).read_text(encoding='utf-8').encode()).hexdigest() == item['before'], name+' changed'
for name, item in DATA['docs'].items():
    (ROOT/name).write_text(item['text'], encoding='utf-8', newline='\n')

paths = sorted(set(DATA['paths']))
for name in paths:
    assert (ROOT/name).is_file(), name
pathfile = ROOT/'tools/vehicle_fleet/review_2034/stage_paths.txt'
pathfile.write_bytes(('\0'.join(paths)+'\0').encode())
subprocess.run(['git','add','--pathspec-from-file='+str(pathfile),'--pathspec-file-nul'],cwd=ROOT,check=True)
staged = set(git('diff','--cached','--name-only').splitlines())
assert staged and staged <= set(paths), 'Unexpected staged scope'
subprocess.run(['git','diff','--cached','--check'],cwd=ROOT,check=True)
print('REVIEWED_SCOPE',len(staged),git('diff','--cached','--shortstat'),flush=True)
result = subprocess.run(['git','commit','-m','Modernize the 2034 fleet and add fourteen distinctive vehicles'],cwd=ROOT,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
print('COMMIT_RESULT',result.returncode,result.stdout[:1100],flush=True)
assert result.returncode == 0, 'Commit failed'
head = git('rev-parse','HEAD')
print('FLEET_2034_COMMIT',head,flush=True)
subprocess.run(['git','push','origin','HEAD:refs/heads/'+BRANCH],cwd=ROOT,check=True)
assert git('ls-remote','origin','refs/heads/'+BRANCH).split()[0] == head
receipt = {'commit':head,'branch':BRANCH,'remote_confirmed':True,'model_checks':3730,'mixed_checks':43,'native_scenarios':6,'models':60,'sprites':1248,'scope_files':len(staged)}
(ROOT/'tools/vehicle_fleet/review_2034/push_receipt.json').write_text(json.dumps(receipt,indent=2))
print('FLEET_2034_PUSH_CONFIRMED',json.dumps(receipt),flush=True)
print('UNRELATED_UNSTAGED',git('diff','--name-only'),flush=True)
